import { emit } from './events';

const PTV = window.PTV || (window.PTV = {});

PTV.observer ||= {};
PTV.observer.callbacks ||= new Set();

let observer = null;
let scheduled = false;

function runCallbacks() {
    scheduled = false;

    for (const callback of PTV.observer.callbacks) {
        try {
            callback();
        } catch (err) {
            console.error('[PiggieTV] Observer callback failed:', err);
        }
    }

    emit('domchange');
}

function scheduleRun() {
    if (scheduled) return;

    scheduled = true;

    requestAnimationFrame(() => {
        requestAnimationFrame(runCallbacks);
    });
}

export function watchDom(callback) {
    if (typeof callback !== 'function') {
        return () => {};
    }

    PTV.observer.callbacks.add(callback);

    scheduleRun();

    return () => {
        PTV.observer.callbacks.delete(callback);
    };
}

export function startObserver() {
    if (observer) return observer;

    observer = new MutationObserver(scheduleRun);

    observer.observe(document.body, {
        childList: true,
        subtree: true
    });

    return observer;
}

export function stopObserver() {
    if (!observer) return;

    observer.disconnect();
    observer = null;
}

startObserver();
